import{b as n,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const p="/assets/image.C1S68KhD.webp",u=JSON.parse('{"title":"JMeter 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/what-is-jmeter/index.md","filePath":"性能测试/1.Jmeter/01.JMeter 是什么.md","lastUpdated":1783947942000}'),o={name:"performance/jmeter/what-is-jmeter/index.md"};function r(l,s,i,d,c,g){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="jmeter-是什么" tabindex="-1">JMeter 是什么 <a class="header-anchor" href="#jmeter-是什么" aria-label="Permalink to &quot;JMeter 是什么&quot;">​</a></h1><blockquote><p>认识 JMeter，掌握两条最重要的核心心法——执行顺序和作用域。地基打牢，后面才不会踩坑。</p></blockquote><h2 id="一句话讲清楚" tabindex="-1">一句话讲清楚 <a class="header-anchor" href="#一句话讲清楚" aria-label="Permalink to &quot;一句话讲清楚&quot;">​</a></h2><p><strong>JMeter 是 Apache 开源的压测工具——用多线程模拟大量用户同时访问你的系统，看系统能不能扛住。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你定义：50 个用户，每人依次做&quot;登录 → 查列表 → 提交&quot;</span></span>
<span class="line"><span>JMeter 干：启动 50 个线程，按你说的流程反复发请求，记录每次耗时</span></span>
<span class="line"><span>你得到：</span></span>
<span class="line"><span>  - 平均多快？</span></span>
<span class="line"><span>  - 最慢多慢？</span></span>
<span class="line"><span>  - 有没有报错？</span></span>
<span class="line"><span>  - 扛到多少人系统开始崩？</span></span></code></pre></div><p><strong>三个要记住的边界</strong>：</p><table tabindex="0"><thead><tr><th>它是</th><th>它不是</th></tr></thead><tbody><tr><td>请求发送器（纯协议层）</td><td>浏览器（不执行 JS，不渲染页面）</td></tr><tr><td>多线程模拟并发</td><td>真实用户在操作</td></tr><tr><td>Java 跨平台工具</td><td>只测 HTTP（也支持 JDBC、TCP、WebSocket 等）</td></tr></tbody></table><h2 id="核心心法一-执行顺序" tabindex="-1">核心心法一：执行顺序 <a class="header-anchor" href="#核心心法一-执行顺序" aria-label="Permalink to &quot;核心心法一：执行顺序&quot;">​</a></h2><blockquote><p>⚠️ <strong>这是最重要的概念</strong>，搞错执行顺序是新手 80% 踩坑的原因。</p></blockquote><p>JMeter <strong>不是按界面上下的顺序执行</strong>的，而是按<strong>元件类型</strong>有固定优先级：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行顺序（从先到后）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  1. 配置元件    Config Elements      ┐</span></span>
<span class="line"><span>  2. 前置处理器  Pre-Processors       │ 发请求前的&quot;准备工作&quot;</span></span>
<span class="line"><span>  3. 定时器      Timers               ┘</span></span>
<span class="line"><span>  4. 取样器      Sampler              ← 发请求（核心动作）</span></span>
<span class="line"><span>  5. 后置处理器  Post-Processors      ┐</span></span>
<span class="line"><span>  6. 断言        Assertions           │ 发完请求后的&quot;检查工作&quot;</span></span>
<span class="line"><span>  7. 监听器      Listeners            ┘</span></span></code></pre></div><p><strong>口诀：配前定，取后断听</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配 → Config      配置先走</span></span>
<span class="line"><span>前 → Pre         前置跟上</span></span>
<span class="line"><span>定 → Timer       定时等待</span></span>
<span class="line"><span>取 → Sampler     发请求！★</span></span>
<span class="line"><span>后 → Post        后置提取</span></span>
<span class="line"><span>断 → Assertion   断言验证</span></span>
<span class="line"><span>听 → Listener    监听记录</span></span></code></pre></div><blockquote><p><strong>记忆场景</strong>：发请求之前要做准备（配、前、定），发完请求才检查结果（后、断、听）。</p></blockquote><p><strong>一个具体的例子</strong>，假设你的脚本长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>界面顺序：                  实际执行顺序：</span></span>
<span class="line"><span>  Pre-Processor A            1. Pre-Processor A     (前置)</span></span>
<span class="line"><span>  Timer B                    2. Timer B             (定时)</span></span>
<span class="line"><span>  HTTP 请求 C                 3. HTTP 请求 C         (取样)</span></span>
<span class="line"><span>  Assertion D                4. Post-Processor E    (后置)</span></span>
<span class="line"><span>  Post-Processor E           5. Assertion D         (断言)</span></span></code></pre></div><blockquote><p>同类元件（比如两个 Timer）则按界面<strong>从上到下</strong>的顺序执行。</p></blockquote><h2 id="核心心法二-作用域规则" tabindex="-1">核心心法二：作用域规则 <a class="header-anchor" href="#核心心法二-作用域规则" aria-label="Permalink to &quot;核心心法二：作用域规则&quot;">​</a></h2><blockquote><p>⚠️ 第二条最重要的概念——元件加在哪，就管到哪。</p></blockquote><p><strong>口诀：父管子，近优先</strong></p><blockquote><p>一个元件&quot;管&quot;的范围，由它<strong>挂在哪个父节点下</strong>决定。JMeter 的树形结构从根到叶依次是：<strong>Test Plan（根节点，每个 .jmx 文件只有一个）→ Thread Group → Controller → Sampler</strong>。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>挂在这下面            →  影响范围</span></span>
<span class="line"><span>──────────────────────────────────────</span></span>
<span class="line"><span>Test Plan 下          →  所有线程组的所有请求</span></span>
<span class="line"><span>Thread Group 下       →  这个线程组的所有请求</span></span>
<span class="line"><span>Logic Controller 下   →  这个控制器里的所有请求</span></span>
<span class="line"><span>单个 Sampler 下       →  只影响这一个请求</span></span></code></pre></div><p><strong>看图就懂</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test Plan</span></span>
<span class="line"><span>  └── Thread Group</span></span>
<span class="line"><span>        ├── 🅐 HTTP Header Manager          ← 对这组里全部请求生效</span></span>
<span class="line"><span>        ├── 🔵 登录请求</span></span>
<span class="line"><span>        │      └── JSON Extractor           ← 只对登录请求生效</span></span>
<span class="line"><span>        ├── 🔵 查列表请求</span></span>
<span class="line"><span>        └── 🔵 提交请求</span></span>
<span class="line"><span>               └── Response Assertion       ← 只对提交请求生效</span></span></code></pre></div><p><strong>&quot;近优先&quot;规则</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test Plan</span></span>
<span class="line"><span>  └── HTTP Header Manager &quot;A&quot;    Content-Type: text/html</span></span>
<span class="line"><span>        └── Thread Group</span></span>
<span class="line"><span>              └── HTTP Header Manager &quot;B&quot;  Content-Type: application/json</span></span>
<span class="line"><span>                    └── HTTP 请求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 请求实际使用的 Content-Type 是 &quot;application/json&quot;（B 离得更近，覆盖了 A）</span></span></code></pre></div><h2 id="元件全景图" tabindex="-1">元件全景图 <a class="header-anchor" href="#元件全景图" aria-label="Permalink to &quot;元件全景图&quot;">​</a></h2><blockquote><p><strong>元件</strong> = JMeter 里右键菜单能添加的每一个功能块（取样器、定时器、断言…），把它们组合起来就是一个压测脚本。</p></blockquote><p>把 JMeter 所有元件按&quot;干活的时间线&quot;排开：</p><p><img src="`+p+'" alt="alt text"></p><table tabindex="0"><thead><tr><th>元件分类</th><th>一句话作用</th><th>口诀关键词</th></tr></thead><tbody><tr><td>配置元件 (Config Element)</td><td>设默认值、管请求头、读数据文件</td><td><strong>配</strong></td></tr><tr><td>前置处理器 (Pre-Processor)</td><td>请求发出前做最后加工</td><td><strong>前</strong></td></tr><tr><td>定时器 (Timer)</td><td>模拟用户停顿思考</td><td><strong>定</strong></td></tr><tr><td>取样器 (Sampler)</td><td>真正发请求的，核心中的核心</td><td><strong>取</strong></td></tr><tr><td>后置处理器 (Post-Processor)</td><td>从响应里提取数据（Token/ID）</td><td><strong>后</strong></td></tr><tr><td>断言 (Assertion)</td><td>检查响应对不对</td><td><strong>断</strong></td></tr><tr><td>监听器 (Listener)</td><td>收集和展示结果</td><td><strong>听</strong></td></tr><tr><td>逻辑控制器 (Logic Controller)</td><td>控制执行流程（if/while/事务）</td><td>—</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一章建立了 JMeter 最核心的认知框架：</p><ul><li><strong>JMeter 是什么</strong>：多线程请求发送器，不是浏览器</li><li><strong>执行顺序</strong>：配前定 → 取 → 后断听（不是界面顺序，是类型优先级）</li><li><strong>作用域</strong>：父管子，近优先（元件挂哪层就管哪层，近的覆盖远的）</li><li><strong>八类元件</strong>：配置元件 (Config Element)、前置处理器 (Pre-Processor)、定时器 (Timer)、取样器 (Sampler)、后置处理器 (Post-Processor)、断言 (Assertion)、监听器 (Listener)、逻辑控制器 (Logic Controller)</li></ul><p>后面所有操作都建立在这两条心法之上。下一章把 JMeter 装好，准备动手。</p>',35)])])}const b=n(o,[["render",r]]);export{u as __pageData,b as default};
